  .grid{
    display:grid;
    grid-template-columns: repeat(4, var(--size));
    grid-template-rows: repeat(4, var(--size));
    gap:var(--gap);
  }
  .cell{
    width:var(--size); height:var(--size);
    background:var(--cell);
    border-radius:4px;
  }

  .tiles{
    position:absolute; inset:var(--gap);
    width:calc(var(--size)*4 + var(--gap)*3);
    height:calc(var(--size)*4 + var(--gap)*3);
  }
  .tile{
