    border-radius:4px;
    display:flex; align-items:center; justify-content:center;
    font-weight:800;
    font-size:42px;
    color:#776e65;
    transition: transform .12s ease-in, left .12s ease-in, top .12s ease-in, background .2s ease-in;
    will-change: transform,left,top;
  }
  .tile.new{animation:pop .12s ease-out}
  @keyframes pop{
    from{transform: scale(0.6)}
    to{transform: scale(1)}
  }

  /* tile colors */
  .v-2  {background:#eee4da}
  .v-4  {background:#ede0c8}
  .v-8  {background:#f2b179;color:#f9f6f2}
  .v-16 {background:#f59563;color:#f9f6f2}
  .v-32 {background:#f67c5f;color:#f9f6f2}
  .v-64 {background:#f65e3b;color:#f9f6f2}
  .v-128{background:#edcf72;color:#f9f6f2;font-size:36px}
  .v-256{background:#edcc61;color:#f9f6f2;font-size:36px}
  .v-512{background:#edc850;color:#f9f6f2;font-size:36px}
  .v-1024{background:#edc53f;color:#f9f6f2;font-size:30px}
  .v-2048{background:#edc22e;color:#f9f6f2;font-size:30px}
  .dim{opacity:.9}

  /* Ad placeholder */
  .ad{
    width:320px; margin:18px auto 26px;
    text-align:center;
  }
  .ad img{width:320px;height:auto;border-radius:6px;display:block;margin:0 auto}

  /* Info bar */
  .info-bar{
    margin-top:12px;
    background:var(--bar);
    padding:18px 20px;
    border-radius:6px;
    line-height:1.55;
    text-align:center;
    color:#7b6a5c;
    max-width:1200px;
  }

  /* Other games */
  .other{
    margin-top:28px;
  }
  .other h2{
    text-align:center;
    margin:4px 0 12px;
  }
  .cards{
    display:flex; gap:18px;
    overflow-x:auto;
    padding:6px 4px 12px;
    scroll-snap-type:x mandatory;
  }
  .card{
    flex:0 0 210px;
    background:#fff;
    border-radius:10px;
    box-shadow:0 1px 0 rgba(0,0,0,.06), 0 2px 12px rgba(0,0,0,.06);
    padding:12px;
    scroll-snap-align:start;
    text-align:center;
  }
  .card img{
    width:100%; height:120px; object-fit:cover; border-radius:8px;
    background:#eee;
  }
  .card .title{font-weight:700;margin:10px 0 8px}
  .play.btn{
    display:inline-block;
    background:#37b24d;
    color:#fff;
    font-weight:700;
    padding:8px 12px;
    border-radius:6px;
    cursor:pointer;
  }

  /* Footer spacing just to mimic screenshots */
  .spacer{height:100px}

  /* Small hint text over title left (+12) */
  .delta{
    position:absolute; left:0; top:0;
    font-size:14px; color:#8f7a66; opacity:.85;
  }

  /* Responsive tweaks */
  @media (max-width:700px){
    :root{ --size:80px; }
    h1{font-size:36px}
    .ad img{width:280px}
  }
</style>
</head>
